                  state.health?.components?.client_manager 
                    ? 'text-emerald-600' 
                    : 'text-red-600'
                }`}>
                  {state.health?.components?.client_manager ? 'Працює' : 'Зупинено'}
                </span>
              </div>

              <div className={`flex items-center justify-between p-3 rounded-lg ${
                state.health?.components?.task_router 
                  ? 'bg-emerald-50' 
                  : 'bg-red-50'
              }`}>
                <div className="flex items-center space-x-2">
                  <div className={`w-3 h-3 rounded-full ${
                    state.health?.components?.task_router 
                      ? 'bg-emerald-500' 
                      : 'bg-red-500'
                  }`}></div>
                  <span className="text-sm font-medium text-slate-700">Task Router</span>
                </div>
                <span className={`text-xs font-semibold ${
                  state.health?.components?.task_router 
                    ? 'text-emerald-600' 
                    : 'text-red-600'
                }`}>
                  {state.health?.components?.task_router ? 'Активний' : 'Неактивний'}
                </span>
              </div>
            </div>

            <div className="mt-6 pt-4 border-t border-slate-200">
              <div className="flex items-center justify-between">
                <span className="text-sm text-slate-600">
                  Версія системи: {state.health?.version || '1.0.0'}
                </span>
                <div className="flex items-center space-x-2">
                  <span className="text-sm text-slate-600">Статус з'єднання</span>
                  <div className="flex items-center space-x-1">
                    <div className={`w-2 h-2 rounded-full ${
                      state.connectionStatus === 'connected' 
                        ? 'bg-emerald-500' 
                        : 'bg-red-500'
                    }`}></div>
                    <span className={`text-sm font-medium ${
                      state.connectionStatus === 'connected' 
                        ? 'text-emerald-600' 
                        : 'text-red-600'
                    }`}>
                      {state.connectionStatus === 'connected' ? 'Онлайн' : 'Офлайн'}
                    </span>
                    <span className="text-sm text-slate-500">{clientStats.connected}</span>
                  </div>
                </div>
              </div>
            </div>
          </div>

          {/* Метрики продуктивності */}
          <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6">
            <h3 className="text-lg font-semibold text-slate-900 mb-6 flex items-center">
              <span className="bg-gradient-to-r from-amber-600 to-amber-800 bg-clip-text text-transparent">
                ⚡ Метрики продуктивності
              </span>
            </h3>

                         <div className="space-y-4">
               <div className="flex items-center justify-between">
                 <span className="text-sm font-medium text-slate-700">Час відповіді</span>
                 <span className="text-2xl font-bold text-blue-600">
                   {Math.round(hubMetrics.response_time)}ms
                 </span>
               </div>

               <div className="flex items-center justify-between">
                 <span className="text-sm font-medium text-slate-700">Пропускна здатність</span>
                 <span className="text-2xl font-bold text-emerald-600">
                   {Math.round(hubMetrics.throughput)} req/s
                 </span>
               </div>

               <div className="flex items-center justify-between">
                 <span className="text-sm font-medium text-slate-700">Рівень помилок</span>
                 <span className={`text-2xl font-bold ${
                   hubMetrics.error_rate > 2 ? 'text-red-600' : 'text-emerald-600'
                 }`}>
                   {hubMetrics.error_rate.toFixed(1)}%
                 </span>
               </div>

               {state.health?.uptime && (
                 <div className="flex items-center justify-between pt-2 border-t border-slate-200">
                   <span className="text-sm font-medium text-slate-700">Час роботи</span>
                   <span className="text-lg font-bold text-purple-600">
                     {Math.floor(state.health.uptime / 3600)}г {Math.floor((state.health.uptime % 3600) / 60)}хв
                   </span>
                 </div>
               )}
             </div>
          </div>
        </div>
      </div>
    </div>
  );
};
